//! 🏗️ The genuine fixture issuer opens actual Core resources under physical grants and compares them with Wasmtime.
use super::*;
use semio_framework_job::{Generation,OperationId,OriginalJobFixtureCaller};
use semio_framework_value::RetainedCloneGrant;
use std::sync::atomic::{AtomicU64,Ordering};
static NOW:AtomicU64=AtomicU64::new(1000);
fn clock()->Option<u64>{Some(NOW.load(Ordering::Acquire))}
fn binary()->Vec<u8>{let mut bytes=b"\0asm\x01\0\0\0".to_vec();for(id,section)in [(4,vec![1,0x70,0,3]),(5,vec![1,0,1]),(6,vec![1,0x7f,0,0x41,7,0x0b]),(7,vec![3,6,b'm',b'e',b'm',b'o',b'r',b'y',2,0,5,b't',b'a',b'b',b'l',b'e',1,0,5,b'v',b'a',b'l',b'u',b'e',3,0]),(11,vec![1,0,0x41,5,0x0b,2,b'2',b'0'])]{bytes.extend([id,section.len()as u8]);bytes.extend(section)}bytes}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
fn observed<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
/// 🧪️ Capacity denial keeps the actual partial owner; bounded initialization produces the same memory, table and global as Wasmtime.
#[test]
fn original_core_opening_phases_actual_storage_and_paid_cancelled_retirement(){
 NOW.store(1000,Ordering::Release);let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let bytes=binary();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let engine=wasmtime::Engine::default();let oracle=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let instance=wasmtime::Instance::new(&mut store,&oracle,&[]).unwrap();let oracle_memory=instance.get_memory(&mut store,"memory").unwrap().data(&store).to_vec();let oracle_table=instance.get_table(&mut store,"table").unwrap().size(&store);let oracle_global=instance.get_global(&mut store,"value").unwrap().get(&mut store).i32().unwrap();
 let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let(owner,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap());assert_eq!(heap,(0,0));let mut owner=owner.unwrap();let mut born=0;let mut denied=false;let phase_grant=RetainedCloneGrant{maximum_copy_bytes:1024,maximum_capacity_bytes:65535,..stock};
 for _ in 0..200{epoch+=1;let(done,heap)=observed(||caller.turn(phase_grant,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;assert!(!done);if let Some(core)=owner.core.as_ref(){if core.memories.first().is_some_and(|memory|memory.bytes.capacity()==0)&&owner.phase==Phase::Memories(0){let before=core.memories[0].bytes.as_ptr();epoch+=1;let(done,heap)=observed(||caller.turn(phase_grant,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert!(!done);assert_eq!(heap,(0,0));assert_eq!(owner.core.as_ref().unwrap().memories[0].bytes.as_ptr(),before);denied=true;break}}}assert!(denied);
 let funded=RetainedCloneGrant{maximum_copy_bytes:1024,maximum_capacity_bytes:65536,..stock};let mut phases=0;while !owner.resources_ready(){epoch+=1;let(done,heap)=observed(||caller.turn(funded,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;phases+=1;assert!(phases<200);if done{break}}
 let core=owner.resources().unwrap();assert_eq!(core.memory(0).unwrap(),oracle_memory);assert_eq!(core.tables[0].values.len()as u64,oracle_table);assert_eq!(core.globals[0].value,Value::I32(oracle_global));assert_eq!(&core.memory(0).unwrap()[fixture["activeOffset"].as_u64().unwrap()as usize..7],fixture["activeData"].as_str().unwrap().as_bytes());assert!(!core.active());assert!(phases>=64);caller.cancel().cancel_now();epoch+=1;assert!(caller.turn(funded,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());let mut released=0;for _ in 0..64{if owner.terminal_is_empty(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual original Core storage phased={phases} denied65535=true accepted65536=true WasmtimeMemoryTableGlobal=true born={born} released={released} cancelledPaidClose=true guestInstructionsNotYetStarted=true");
}

fn scalar_binary()->Vec<u8>{let mut bytes=b"\0asm\x01\0\0\0".to_vec();let mut leb=Vec::new();let mut value=(2u64<<32)|5;loop{let byte=(value&127)as u8;value>>=7;let done=value==0&&byte&64==0;leb.push(byte|if done{0}else{128});if done{break}}let mut body=vec![0,0x42];body.extend(leb);body.push(0x0b);let mut code=vec![1,body.len()as u8];code.extend(body);for(id,section)in[(1,vec![1,0x60,0,1,0x7e]),(3,vec![1,0]),(5,vec![1,0,1]),(7,vec![2,6,b'm',b'e',b'm',b'o',b'r',b'y',2,0,7,b'v',b'e',b'r',b's',b'i',b'o',b'n',0,0]),(10,code),(11,vec![1,0,0x41,5,0x0b,2,b'2',b'0'])]{bytes.extend([id,section.len()as u8]);bytes.extend(section)}bytes}
/// ▶️ Real instruction cost remains distinct from physical admission and a borrowed completed result survives until paid closure.
#[test]
fn original_core_scalar_startup_measures_execution_without_replacing_original_currency(){
 NOW.store(1000,Ordering::Release);let bytes=scalar_binary();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let engine=wasmtime::Engine::default();let oracle=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let instance=wasmtime::Instance::new(&mut store,&oracle,&[]).unwrap();let expected=instance.get_typed_func::<(),i64>(&mut store,"version").unwrap().call(&mut store,()).unwrap();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;let phased=RetainedCloneGrant{maximum_copy_bytes:1024,..stock};while !owner.resources_ready(){epoch+=1;let(_,heap)=observed(||caller.turn(phased,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());born+=heap.0;assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap)}let function=match module.export("version").unwrap(){ExportKind::Function(function)=>*function,_=>panic!()};epoch+=1;let(ready,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.begin_function_step(&module,function,&[],cx)}).unwrap());assert!(ready);assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;
 let mut measured=0;for _ in 0..2{epoch+=1;let(call,heap)=observed(||caller.turn(phased,|cx|{cx.bind_original_source_epoch(epoch)?;let execution=semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,fuel:1,deadline_us:cx.deadline_us()};let wrong=semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput{generation:4,..execution.input},..execution};assert!(owner.advance_scalar(&module,wrong,cx).is_err());owner.advance_scalar(&module,execution,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;assert_eq!(call.execution.spent_fuel,Some(1));measured+=call.execution.spent_fuel.unwrap();if measured==1{assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);assert!(owner.invocation_values().is_none())}else{assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Complete);assert_eq!(owner.invocation_values().unwrap(),&[Value::I64(expected)])}}
 assert_eq!(measured,2);caller.cancel().cancel_now();let mut released=0;for _ in 0..80{if owner.terminal_is_empty(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap());released+=heap.1;assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap)}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual original Core scalar startup WasmtimeResult={expected} measuredVMInstructions={measured} physicalBirth={born} physicalRelease={released} oneInstructionSlices=true wrongIdentityRefused=true resultBorrowedUntilPaidClose=true");
}

/// 🛑️ Cancellation and a foreign same-named issuer preserve the actual partially born storage and its source until paid return.
#[test]
fn original_core_partial_cancel_and_foreign_source_preserve_actual_retained_owner(){
 NOW.store(1000,Ordering::Release);let module=Arc::new(CoreModule::parse(&binary()).unwrap());let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;for _ in 0..16{epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;if owner.core.as_ref().unwrap().memories.first().is_some_and(|memory|memory.bytes.capacity()==65536){break}}let pointer=owner.core.as_ref().unwrap().memories[0].bytes.as_ptr();assert_eq!(owner.core.as_ref().unwrap().memories[0].bytes.len(),0);assert!(!owner.resources_ready());let mut foreign=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let(result,heap)=observed(||foreign.turn(stock,|cx|{cx.bind_original_source_epoch(epoch+1)?;owner.advance(&module,cx)}));assert!(result.is_err());assert_eq!(heap,(0,0));foreign.retire(stock);caller.cancel().cancel_now();epoch+=1;let(result,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert!(!result);assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),RetainedCloneProgress::default());assert_eq!(owner.core.as_ref().unwrap().memories[0].bytes.as_ptr(),pointer);assert_eq!(owner.core.as_ref().unwrap().memories[0].bytes.len(),0);let mut released=0;for _ in 0..80{if owner.terminal_is_empty(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual partial Core cancelledBeforeInitialization=true foreignSameBusinessIdentityRefused=true sameRetainedAddress=true physicalBirth={born} paidRelease={released} noForeignReceipt=true");
}

/// 📥️ A borrowed input copies into already born guest memory only under its genuine incoming source and copy grant.
#[test]
fn original_core_input_memory_copy_preserves_denied_cursor_and_matches_wasmtime(){
 NOW.store(1000,Ordering::Release);let bytes=binary();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let engine=wasmtime::Engine::default();let compiled=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let instance=wasmtime::Instance::new(&mut store,&compiled,&[]).unwrap();let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let source=fixture["inputCopy"]["source"].as_str().unwrap().as_bytes();assert_eq!(size_of::<usize>(),fixture["inputCopy"]["cursorBytes"].as_u64().unwrap()as usize);instance.get_memory(&mut store,"memory").unwrap().write(&mut store,100,source).unwrap();let expected=instance.get_memory(&mut store,"memory").unwrap().data(&store).to_vec();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;while !owner.resources_ready(){epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;}let mut copied=0;epoch+=1;let(done,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:size_of::<usize>()-1,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;owner.write_original_memory_step(&module,0,100,source,&mut copied,cx)}).unwrap());assert!(!done);assert_eq!(heap,(0,0));assert_eq!(copied,0);assert_eq!(caller.receipt(),Default::default());let mut phases=0;while copied<source.len(){epoch+=1;let(_,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:32,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;owner.write_original_memory_step(&module,0,100,source,&mut copied,cx)}).unwrap());assert_eq!(heap,(0,0));assert!(caller.receipt().copied_bytes<=32);phases+=1;assert!(phases<4)}assert_eq!(owner.resources().unwrap().memory(0).unwrap(),expected);let mut released=0;for _ in 0..80{if owner.terminal_is_empty(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual original input borrowedBytes={} phasedCopies={phases} copy32IncludesCursor=true deniedCursor7=true WasmtimeMemory=true noNativeBirthOrReleaseDuringCopy=true paidTerminalRelease={released}",source.len());
}

/// 📞️ Nested calls preserve their denied operands and return each funded physical frame separately from eight actual VM instructions.
#[test]
fn original_core_nested_call_pays_each_frame_and_preserves_denied_operands(){
 NOW.store(1000,Ordering::Release);let fixture:serde_json::Value=serde_json::from_str(include_str!("../▶️invocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes:Vec<u8>=fixture["moduleHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let engine=wasmtime::Engine::default();let oracle=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let instance=wasmtime::Instance::new(&mut store,&oracle,&[]).unwrap();let expected=instance.get_typed_func::<(),i64>(&mut store,"invoke").unwrap().call(&mut store,()).unwrap();assert_eq!(expected,fixture["expected"].as_i64().unwrap());let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;let mut released=0;while !owner.resources_ready(){epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}epoch+=1;let(ready,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.begin_function_step(&module,0,&[],cx)}).unwrap());assert!(ready);assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;let mut vm=0;
 for _ in 0..2{epoch+=1;let(call,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap());assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);vm+=call.execution.spent_fuel.unwrap();assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}let core=owner.core.as_ref().unwrap();let machine=core.machine.as_ref().unwrap();let before=(machine.frames.len(),machine.frames[0].pc,machine.values.clone(),machine.values.as_ptr());epoch+=1;let(call,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_capacity_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap());assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);assert_eq!(call.execution.spent_fuel,Some(0));assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());let machine=owner.core.as_ref().unwrap().machine.as_ref().unwrap();assert_eq!((machine.frames.len(),machine.frames[0].pc,machine.values.as_slice(),machine.values.as_ptr()),(before.0,before.1,before.2.as_slice(),before.3));let mut physical_only=0;for _ in 0..100{epoch+=1;let(call,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;let instructions=call.execution.spent_fuel.unwrap();vm+=instructions;if instructions==0{physical_only+=1;}if call.result.unwrap()==CoreOriginalInvocationStatus::Complete{break}}assert_eq!(owner.invocation_values().unwrap(),&[Value::I64(expected)]);assert_eq!(vm,fixture["expectedInstructions"].as_u64().unwrap());assert!(physical_only>0);caller.cancel().cancel_now();for _ in 0..100{if owner.terminal_is_empty(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual nested original callee WasmtimeScalar={expected} measuredVM={vm} deniedCapacity0PreservesOperands=true physicalOnlyReturns={physical_only} born={born} paidRelease={released} cancelledFinalClose=true");
}

/// 📥️ Actual memory load/store instructions quote all guest-byte and machine mutations before changing address, operands or PC.
#[test]
fn original_core_memory_instruction_preserves_denied_store_and_matches_wasmtime(){
 NOW.store(1000,Ordering::Release);let fixture:serde_json::Value=serde_json::from_str(include_str!("../▶️invocation/📥️memory/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes:Vec<u8>=fixture["moduleHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let engine=wasmtime::Engine::default();let oracle=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let instance=wasmtime::Instance::new(&mut store,&oracle,&[]).unwrap();let expected=instance.get_typed_func::<(),i64>(&mut store,"invoke").unwrap().call(&mut store,()).unwrap();assert_eq!(expected,fixture["expected"].as_i64().unwrap());let address=fixture["address"].as_u64().unwrap()as usize;let width=fixture["width"].as_u64().unwrap()as usize;let expected_bytes=instance.get_memory(&mut store,"memory").unwrap().data(&store)[address..address+width].to_vec();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;let mut released=0;while !owner.resources_ready(){epoch+=1;let(_,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:1024,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}epoch+=1;let(ready,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.begin_function_step(&module,0,&[],cx)}).unwrap());assert!(ready);assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;let mut vm=0;
 for _ in 0..2{epoch+=1;let(call,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap());assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);vm+=call.execution.spent_fuel.unwrap();assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}let machine=owner.core.as_ref().unwrap().machine.as_ref().unwrap();let before=(machine.frames[0].pc,machine.values.clone(),machine.values.as_ptr());let memory=owner.resources().unwrap().memory(0).unwrap();let original_memory_pointer=memory.as_ptr();assert_eq!(&memory[address..address+width],&[0;8]);epoch+=1;let(call,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:fixture["deniedCopyBytes"].as_u64().unwrap()as usize,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap());assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);assert_eq!(call.execution.spent_fuel,Some(0));assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());let machine=owner.core.as_ref().unwrap().machine.as_ref().unwrap();assert_eq!((machine.frames[0].pc,machine.values.as_slice(),machine.values.as_ptr()),(before.0,before.1.as_slice(),before.2));assert_eq!(&owner.resources().unwrap().memory(0).unwrap()[address..address+width],&[0;8]);for _ in 0..20{epoch+=1;let(call,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput::borrow_original(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;vm+=call.execution.spent_fuel.unwrap();if call.result.unwrap()==CoreOriginalInvocationStatus::Complete{break}}assert_eq!(owner.invocation_values().unwrap(),&[Value::I64(expected)]);assert_eq!(vm,fixture["expectedInstructions"].as_u64().unwrap());let memory=owner.resources().unwrap().memory(0).unwrap();assert_eq!(memory.as_ptr(),original_memory_pointer);assert_eq!(&memory[address..address+width],expected_bytes.as_slice());caller.cancel().cancel_now();for _ in 0..100{if owner.terminal_is_empty(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual original memory instructions WasmtimeScalar={expected} VM={vm} deniedCopy7PreservesBytesOperandsPC=true sameFundedMemory=true exactStoredBytes=true physicalBirth={born} paidRelease={released} cancelledPaidClose=true");
}
